    agent_pos = observation.get('agent_pos', (0, 0))
    target_pos = observation.get('target_pos')
    enemies = observation.get('enemies', [])
    resources = observation.get('resources', [])
    territory = observation.get('territory', [])

    dx, dy = 0, 0

    # Helper function to compute Manhattan distance
    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1]) if a is not None and b is not None else float('inf')

    # Determine goal based on scenario
    # Priority 1: Pursuit/evasion if enemies are present
    if enemies:
        # Find closest enemy
        closest_enemy = min(enemies, key=lambda e: dist(agent_pos, e))
        ex, ey = closest_enemy
        ax, ay = agent_pos
        if ex > ax:
