        elif ex < ax:
            dx = -1
        else:
            dx = 0
        if ey > ay:
            dy = 1
        elif ey < ay:
            dy = -1
        else:
            dy = 0
        # If adjacent, stay still
        if abs(dx) + abs(dy) == 0:
            dx, dy = 0, 0
        return [dx, dy]

    # Priority 2: Collect resources
    if resources:
        closest_res = min(resources, key=lambda r: dist(agent_pos, r))
        rx, ry = closest_res
        ax, ay = agent_pos
        if rx > ax:
            dx = 1
        elif rx < ax:
            dx = -1
        else:
            dx = 0
        if ry > ay:
            dy = 1
        elif ry < ay:
            dy = -1
        else:
            dy = 0
        # If already at resource, stay
        if (ax, ay) == (rx, ry):
            dx, dy = 0, 0
        return [dx, dy]

    # Priority 3: Territory expansion
    # Find unclaimed territory adjacent
    # Check only immediate neighboring cells
    ax, ay = agent_pos
    neighbors = [ (ax+1, ay), (ax-1, ay), (ax, ay+1), (ax, ay-1) ]
    for nx, ny in neighbors:
        # Check bounds if 'field' info is available
        if field:
            bounds_x = len(field)
            bounds_y = len(field[0]) if bounds_x > 0 else 0
            if 0 <= nx < bounds_x and 0 <= ny < bounds_y:
                if field[nx][ny] != 'claimed':
                    move_dx = nx - ax
                    move_dy = ny - ay
                    # Map to -1, 0, 1
                    move_dx = 0 if move_dx == 0 else (1 if move_dx > 0 else -1)
                    move_dy = 0 if move_dy == 0 else (1 if move_dy > 0 else -1)
                    return [move_dx, move_dy]
        else:
            # Without field info, move towards unclaimed territory heuristically
            # For simplicity, move randomly to a valid direction
            return [0, 1]  # default move upwards

    # Default action: stay still
    return [0, 0]

